import{_ as a,a as o,b as i,c as t}from"./chunks/holybro_sik_longrange_include2.EaWtX9Az.js";import{_ as r,o as l,c as n,al as s}from"./chunks/framework.7vp1BMOE.js";const y=JSON.parse('{"title":"Holybro SiK Telemetry Radio - Long Range","description":"","frontmatter":{},"headers":[],"relativePath":"ko/telemetry/holybro_sik_longrange.md","filePath":"ko/telemetry/holybro_sik_longrange.md"}'),d={name:"ko/telemetry/holybro_sik_longrange.md"};function c(h,e,u,p,g,m){return l(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="holybro-sik-telemetry-radio-long-range" tabindex="-1">Holybro SiK Telemetry Radio - Long Range <a class="header-anchor" href="#holybro-sik-telemetry-radio-long-range" aria-label="Permalink to &quot;Holybro SiK Telemetry Radio - Long Range&quot;">​</a></h1><p>This Holybro SiK Long Range Telemetry Radio is a small, light, and inexpensive open-source radio platform with an extended range (~20km) compared to the standard model.</p><p>This radio is plug-and-play, ready for all Pixhawk Standard and other similar flight controllers, providing the easiest way to set up a telemetry connection between your controller and a ground station. It uses open-source firmware that has been specially designed to work well with MAVLink packets and to be integrated with PX4, ArduPilot, Mission Planner and QGroundControl.</p><p>The radios are available in 915 MHz or 433 MHz versions. Please purchase the model that is appropriate for your country/region.</p><p><img src="'+a+'" alt="Sik Telemetry Radio - Long Range"></p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><ul><li><a href="https://holybro.com/collections/telemetry-radios/products/sik-telemetry-radio-1w" target="_blank" rel="noreferrer">Holybro SiK Telemetry Radio - Long Range</a></li></ul><h2 id="특징" tabindex="-1">특징 <a class="header-anchor" href="#특징" aria-label="Permalink to &quot;특징&quot;">​</a></h2><ul><li>1W maximum RF output and up to 20km range (compared to 100mW/300m for the short range version).</li><li>Open-source SIK firmware</li><li>Plug-n-play for Pixhawk Standard Flight Controllers</li><li>The Easiest way to connect your controller and Ground Station</li><li>Interchangeable air and ground radio</li><li>6-position JST-GH connector</li></ul><h2 id="사양" tabindex="-1">사양 <a class="header-anchor" href="#사양" aria-label="Permalink to &quot;사양&quot;">​</a></h2><ul><li>1 W maximum output power (adjustable) -117 dBm receive sensitivity</li><li>RP-SMA connector</li><li>2-way full-duplex communication through adaptive TDM UART interface</li><li>Transparent serial link</li><li>MAVLink protocol framing</li><li>Frequency Hopping Spread Spectrum (FHSS) Configurable duty cycle</li><li>Error correction corrects up to 25% of bit errors Open-source SIK firmware</li><li>Configurable through Mission Planner &amp; APM Planner</li><li>FT230X USB to BASIC UART IC</li><li>USB Type C connector</li><li>XT30 power connector for 7~28V DC input</li></ul><h2 id="leds-indicators-status" tabindex="-1">LEDs Indicators Status <a class="header-anchor" href="#leds-indicators-status" aria-label="Permalink to &quot;LEDs Indicators Status&quot;">​</a></h2><p>The radios have four status LEDs. The USB <code>RX</code> and <code>TX</code> LEDs indicate the status of reception and transmission of the USB port. The <code>RADIO</code> and <code>ACT</code> two LED lights indicate the status of the RF circuit.</p><ul><li>USB-TX LED (orange): <ul><li>Blinking: USB port has data transmission</li><li>Off: USB port has no data transmission</li></ul></li><li>USB-RX LED (orange): <ul><li>Blinking: USB port has data reception</li><li>Off: USB port has no data reception</li></ul></li><li>Radio LED (Green) <ul><li>Blinking: Searching for another radio</li><li>Solid: Link is established with another radio</li></ul></li><li>ACT LED (Red) <ul><li>Flashing: Transmitting data</li><li>Solid: In firmware update mode</li></ul></li></ul><p><img src="'+o+'" alt="Holybro SiK LongRange LED Indicators"></p><h2 id="connecting-to-flight-controller" tabindex="-1">Connecting to Flight Controller <a class="header-anchor" href="#connecting-to-flight-controller" aria-label="Permalink to &quot;Connecting to Flight Controller&quot;">​</a></h2><p>Supply the power (7~28V) to the radio via the XT30 connector. Use the 6-pin JST-GH connector that comes with the radio to connect the radio to your flight controller&#39;s <code>TELEM1</code> port.</p><p>Note that <code>TELEM2</code> can also be used, but you may need to <a href="./../peripherals/mavlink_peripherals">configure the telemetry port</a> on some flight controllers.</p><h2 id="connecting-to-a-pc-or-ground-station" tabindex="-1">Connecting to a PC or Ground Station <a class="header-anchor" href="#connecting-to-a-pc-or-ground-station" aria-label="Permalink to &quot;Connecting to a PC or Ground Station&quot;">​</a></h2><p>First, power the module with a 7~28V DC source. Then, connect the radio to your Windows PC or Ground Station using a Type-C USB cable.</p><p>The necessary drivers should be installed automatically, and the radio will appear as a new “USB Serial Port” in the Windows Device Manager under Ports (COM &amp; LPT). The Mission Planner&#39;s COM Port selection drop-down should also include the newly added COM port.</p><h2 id="packages-include" tabindex="-1">Packages Include <a class="header-anchor" href="#packages-include" aria-label="Permalink to &quot;Packages Include&quot;">​</a></h2><h3 id="single-radio" tabindex="-1">Single Radio <a class="header-anchor" href="#single-radio" aria-label="Permalink to &quot;Single Radio&quot;">​</a></h3><ul><li>1W Radio modules with antennas (1)</li><li>High-gain omnidirectional antenna (1)</li><li>Male Type-C to male Type-C USB cable (1)</li><li>Male XT30 to female XT30 adapter cable (1)</li><li>Male XT30 to female XT60 adapter cable (1)</li><li>JST-GH-6P to JST-GH-6P cable (1) (for Pixhawk Standard FC)</li><li>Rubber damping grommet (3)</li></ul><p><img src="'+i+'" alt="Sik Telemetry Radio - LongRange Package1"></p><h3 id="pair-radios" tabindex="-1">Pair Radios <a class="header-anchor" href="#pair-radios" aria-label="Permalink to &quot;Pair Radios&quot;">​</a></h3><ul><li>1W Radio modules with antennas (2)</li><li>High-gain omnidirectional antenna (2)</li><li>Male Type-C to male Type-C USB cable (1)</li><li>Male XT30 to female XT30 adapter cable (1)</li><li>Male XT30 to female XT60 adapter cable (1)</li><li>JST-GH-6P to JST-GH-6P cable (1) (for Pixhawk Standard FC)</li><li>Rubber damping grommet (3)</li></ul><p><img src="'+t+'" alt="Sik Telemetry Radio - LongRange Package2"></p>',28)])])}const S=r(d,[["render",c]]);export{y as __pageData,S as default};
